// THROWAWAY: extend R shell/samples/lane layout. Three layouts, no production imports or persistence.
const demoDate='2026-10-10', refineVariants={A:['一屏概览','紧凑日轴 · 就近浮窗 · 底部背景'],B:['精细右栏','精细日轴 · 常驻详情 · 侧栏背景'],C:['按需聚焦','概览＋时段放大 · 浮层背景']};
Object.assign(variants,refineVariants);pages.habits='习惯';
variant=refineVariants[params.get('variant')]?params.get('variant'):'A';page=pages[params.get('page')]?params.get('page'):'today';
let focusBand='all',zoomMode='default',axisExpanded=false,detailKind=null,selectedPlan=null,taskDraft=null,taskDraftId=null,folderOpen=true,taskSort='date',priorityFilter='',tagFilter='',holidayVisible=true,previewTab='plan',habitSelected='h1',showInactive=false,voiceState='idle',voiceText='',voiceExpanded=true,slashIndex=0;
let refineChanges=[];
const demoLists=[{name:'Inbox',folder:null},{name:'工作',folder:'生活与工作'},{name:'家务',folder:'生活与工作'},{name:'以后想做',folder:null}];
function prepareTasks(){tasks=structuredClone(revisionInitialTasks);tasks.forEach((t,i)=>Object.assign(t,{priority:i===1?'高':i===0?'中':'无',tags:i===1?['规划']:i===2?['家务']:[],parent:null,state:t.done?'done':'pending',duration:t.time==null?null:t.duration}));tasks.push({id:'t7',name:'整理已收集的事项',note:'只盘点已有内容，不新增计划。',date:demoDate,time:null,duration:null,list:'工作',priority:'低',tags:['规划'],parent:'t2',state:'pending',done:false},{id:'t8',name:'归拢待回复事项',note:'这是子任务的子任务，拥有独立日期和状态。',date:'2026-10-12',time:660,duration:15,list:'工作',priority:'无',tags:[],parent:'t7',state:'pending',done:false},{id:'t9',name:'洗衣服',note:'深色衣物单独洗。',date:demoDate,time:1080,duration:45,list:'家务',priority:'低',tags:['家务'],parent:null,state:'pending',done:false});}
prepareTasks();plans=structuredClone(revisionInitialPlans);plans.find(p=>p.id==='p2').band='下午';baseline.splice(0,baseline.length,...structuredClone(plans));
const savedBaseline=structuredClone(baseline);
const dateFor=n=>`2026-10-${String(n).padStart(2,'0')}`;
const minuteOf=v=>v?+v.slice(0,2)*60+(+v.slice(3)):null;
const timeField=m=>m==null?'':time(m);
const goalLabel=g=>g.frequency==='weekly'?`每周 ${g.target} 天`:g.kind==='threshold'?`每天 ${g.threshold} 前`:'每天达标';
function changeRecord(kind,id,before,after){refineChanges.push({kind,id,before:structuredClone(before),after:structuredClone(after)});}
commitPlan=(id,next,reason)=>{const p=plans.find(x=>x.id===id),before=structuredClone(p);Object.assign(p,next);changeRecord(reason,id,before,p);recordRevision++;render();notify('当前安排已更新，早间基准保留')};
const refinePlanLabel=p=>p.start==null?p.band:`${time(p.start)}–${time(p.end)}`;
showMarkdown=()=>{const d=$('#state-dialog');d.innerHTML='<h2>内存中的 Daily Record</h2><pre></pre><button class="btn">关闭</button>';d.querySelector('pre').textContent=dailyMarkdown();d.querySelector('button').onclick=()=>d.close();d.showModal()};
function captureEditor(){const f=$('#refine-task-form');if(f){taskDraft=readTaskForm(f);taskDraftId=f.dataset.id;}}
function readTaskForm(f){const v=new FormData(f),start=minuteOf(v.get('time')),end=minuteOf(v.get('end'));return {name:String(v.get('name')).trim(),note:String(v.get('note')),date:String(v.get('date'))||null,time:start,duration:start!=null&&end!=null?end-start:null,list:String(v.get('list')),priority:String(v.get('priority')),tags:String(v.get('tags')).split(/[,，]/).map(x=>x.trim()).filter(Boolean),parent:String(v.get('parent'))||null};}
function listOptions(selected){return demoLists.map(l=>`<option ${l.name===selected?'selected':''}>${esc(l.name)}</option>`).join('')}
function taskEditor(t,newTask=false){const id=t.id||'new',v=taskDraftId===id&&taskDraft?{...t,...taskDraft}:t;
 const list=`<details class="property-chip"><summary>▤ ${esc(v.list)}</summary><label>清单<select name="list">${listOptions(v.list)}</select></label></details>`;
 const date=`<details class="property-chip"><summary>▦ ${v.date||'未排期'}</summary><label>日期<input name="date" type="date" value="${v.date||''}"></label></details>`;
 const timing=`<details class="property-chip"><summary>◷ ${v.time==null?'时间未定':time(v.time)+(v.duration!=null?'–'+time(v.time+v.duration):'')}</summary><div class="time-pair"><label>开始<input type="time" name="time" value="${timeField(v.time)}"></label><label>结束<input type="time" name="end" value="${v.time!=null&&v.duration!=null?time(v.time+v.duration):''}"></label></div><button type="button" class="text-button clear-end" ${v.duration==null?'hidden':''}>清除结束时间</button></details>`;
 const extra=`<details class="property-chip extra-properties" ${variant==='C'?'open':''}><summary>优先级 · 标签 · 父任务</summary><label>优先级<select name="priority">${['无','高','中','低'].map(x=>`<option ${v.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>标签<input name="tags" value="${esc((v.tags||[]).join(', '))}" placeholder="规划, 家务"></label><label>父任务<select name="parent"><option value="">无父任务</option>${tasks.filter(x=>x.id!==id&&!isDescendant(x.id,id)).map(x=>`<option value="${x.id}" ${v.parent===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></details>`;
 const children=tasks.filter(x=>x.parent===id);
 return `<form id="refine-task-form" data-id="${id}"><div class="editor-head"><span class="tiny muted">${newTask?'新任务':`Task · ${id}`}</span><button type="button" class="text-button editor-close" aria-label="关闭详情">✕</button></div><input class="editable-title" aria-label="任务标题" name="name" value="${esc(v.name||'')}" placeholder="任务名称" required>${variant==='A'?`<div class="property-row">${list}${date}${timing}</div>`:''}<label class="content-label" for="task-content">Content</label><textarea id="task-content" name="note" placeholder="补充内容…">${esc(v.note||'')}</textarea><div class="property-row">${variant!=='A'?list+date+timing:''}${extra}</div>${v.parent?`<button type="button" class="text-button" data-open-parent="${v.parent}">↑ 查看父任务</button>`:''}<div class="subtask-section"><div class="section-title"><b>子任务 · ${children.length}</b>${newTask?'':`<button type="button" class="text-button" data-add-child="${id}">＋ 子任务</button>`}</div>${children.map(x=>taskRow(x)).join('')}</div><div class="editor-footer"><button class="btn primary">${newTask?'创建':'Save'}</button><button type="button" class="btn editor-cancel">Cancel</button>${newTask?'':`<button type="button" class="text-button editor-more" data-more="${id}">More ···</button>`}</div></form>`;
}
function isDescendant(id,ancestor){let t=taskById(id),seen=new Set();while(t?.parent&&!seen.has(t.id)){seen.add(t.id);if(t.parent===ancestor)return true;t=taskById(t.parent)}return false;}
taskRow=(t)=>`<div class="task-row ${t.done?'done':''} ${t.id===selectedTask?'selected':''}" data-context-task="${t.id}"><input type="checkbox" data-complete="${t.id}" aria-label="完成 ${esc(t.name)}" ${t.done?'checked':''}><div class="task-body"><button class="task-name" data-task="${t.id}">${t.parent?'↳ ':''}${esc(t.name)}</button></div>${t.priority==='高'?'<span class="priority-mark">!</span>':''}<span class="date-chip">${t.state==='abandoned'?'已放弃':t.date===demoDate?(t.time==null?'今天':time(t.time)):t.date?.slice(5)||'未排期'}</span><button class="text-button" data-more="${t.id}" aria-label="更多操作 ${esc(t.name)}">···</button></div>`;
quickAdd=()=>`<form class="refine-quick" data-quick-form><input name="name" aria-label="快速添加任务" placeholder="＋ 添加一个任务" required><div class="quick-options"><label>日期<input name="date" type="date" value="${demoDate}"></label><label>目标清单<select name="list">${listOptions(demoLists.some(l=>l.name===scope)?scope:'Inbox')}</select></label><button class="btn primary">添加</button></div></form>`;
filteredTasks=()=>{let list=tasks.filter(t=>scope==='all'||scope==='today'&&t.date===demoDate||scope==='inbox'&&t.list==='Inbox'||scope==='folder'&&['工作','家务'].includes(t.list)||scope===t.list);if(priorityFilter)list=list.filter(t=>t.priority===priorityFilter);if(tagFilter)list=list.filter(t=>t.tags.includes(tagFilter));return list.sort((a,b)=>taskSort==='priority'?['高','中','低','无'].indexOf(a.priority)-['高','中','低','无'].indexOf(b.priority):(a.date||'9999').localeCompare(b.date||'9999')||(a.time??1440)-(b.time??1440))};
function refineListRail(){return `<aside class="refine-lists"><h2>清单</h2>${[['all','All'],['today','Today'],['inbox','Inbox']].map(([k,n])=>`<button data-scope="${k}" class="rail-item ${scope===k?'active':''}">${n}</button>`).join('')}<hr><div class="folder-heading"><button id="folder-arrow" aria-label="展开或收起文件夹">${folderOpen?'▾':'▸'}</button><button data-scope="folder" class="${scope==='folder'?'active':''}">生活与工作</button></div>${folderOpen?['工作','家务'].map(n=>`<button class="rail-item nested ${scope===n?'active':''}" data-scope="${n}">${n}</button>`).join(''):''}<button class="rail-item ${scope==='以后想做'?'active':''}" data-scope="以后想做">以后想做</button></aside>`;}
taskPage=()=>{const list=filteredTasks(),pending=list.filter(t=>!t.done&&t.state!=='abandoned'),other=list.filter(t=>t.done||t.state==='abandoned'),groups=scope==='folder'?['工作','家务']:[null];return header('任务','同一 Task · 紧凑列表与右栏',btn('＋ 新任务','new-task','primary'))+`<section class="surface refine-task-layout">${refineListRail()}<div class="refine-task-list"><div class="section-title"><h2>${scope==='folder'?'生活与工作':scope==='all'?'All':scope==='today'?'Today':scope==='inbox'?'Inbox':scope}</h2><span class="tiny muted">${pending.length} 待办</span></div>${quickAdd()}<div class="filter-row"><select id="task-sort" aria-label="任务排序"><option value="date" ${taskSort==='date'?'selected':''}>按日期</option><option value="priority" ${taskSort==='priority'?'selected':''}>按优先级</option></select><select id="priority-filter" aria-label="优先级筛选"><option value="">所有优先级</option>${['高','中','低','无'].map(x=>`<option ${priorityFilter===x?'selected':''}>${x}</option>`).join('')}</select><select id="tag-filter" aria-label="标签筛选"><option value="">所有标签</option>${[...new Set(tasks.flatMap(t=>t.tags))].map(x=>`<option ${tagFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>${groups.map(g=>`${g?`<h3 class="list-group-label">${g}</h3>`:''}${pending.filter(t=>g==null||t.list===g).map(taskRow).join('')}`).join('')}${other.length?`<details class="completed-list"><summary>已完成 / 已放弃 · ${other.length}</summary>${other.map(taskRow).join('')}</details>`:''}</div><aside class="refine-detail">${selectedTask&&taskById(selectedTask)?taskEditor(taskById(selectedTask)):'<p class="muted">选择任务查看 Content</p>'}</aside></section>`;};
function openRefineTask(t=null,start=null,end=null,date=demoDate,parent=null){taskDraft=null;taskDraftId=null;const value=t||{id:'new',name:'',note:'',list:parent?taskById(parent).list:'Inbox',date,time:start,duration:end!=null?end-start:null,priority:'无',tags:[],parent};const d=$('#detail-dialog');d.className='refine-task-dialog';d.innerHTML=taskEditor(value,!t);if(!d.open)d.showModal();bindTaskEditor(d,value,!t);if(t)$('#task-content').focus();else d.querySelector('[name=name]').focus();}
openTaskDialog=openRefineTask;
selectTask=id=>{captureEditor();selectedTask=id;selectedPlan=null;detailKind='task';taskDraft=null;taskDraftId=null;if(page==='tasks'||page==='today'&&variant==='B'){render();$('#task-content')?.focus()}else openRefineTask(taskById(id));};
function bindTaskEditor(root,t,isNew){const f=root.querySelector('#refine-task-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const next=readTaskForm(f);if(!next.name)return;if(next.time!=null&&next.duration!=null&&next.duration<=0){notify('结束时间需晚于开始');return}if(next.time!=null&&!next.date){notify('请先设置日期');return}if(isNew){const added={...next,id:'demo-'+Date.now(),state:'pending',done:false};tasks.push(added);selectedTask=added.id;changeRecord('create-task',added.id,null,added)}else{const before=structuredClone(t);Object.assign(t,next);changeRecord('edit-task',t.id,before,t)}taskDraft=null;taskDraftId=null;$('#detail-dialog').close();render();notify(isNew?'已创建共享 Task':'Task 已保存')};f.querySelector('.clear-end').onclick=()=>{f.elements.end.value='';f.querySelector('.clear-end').hidden=true};f.elements.end.oninput=()=>f.querySelector('.clear-end').hidden=!f.elements.end.value;const close=()=>{taskDraft=null;taskDraftId=null;if($('#detail-dialog').open)$('#detail-dialog').close();else{selectedTask=null;detailKind=null;render()}};f.querySelector('.editor-close').onclick=close;f.querySelector('.editor-cancel').onclick=()=>{taskDraft=null;taskDraftId=null;if(isNew)close();else if($('#detail-dialog').open)openRefineTask(t);else render()};f.querySelectorAll('[data-more]').forEach(b=>b.onclick=e=>openMore(t.id,e));f.querySelectorAll('[data-add-child]').forEach(b=>b.onclick=()=>{if($('#detail-dialog').open)$('#detail-dialog').close();openRefineTask(null,null,null,demoDate,b.dataset.addChild)});f.querySelectorAll('[data-task],[data-open-parent]').forEach(b=>b.onclick=()=>{if($('#detail-dialog').open)$('#detail-dialog').close();selectTask(b.dataset.task||b.dataset.openParent)});f.querySelectorAll('[data-complete]').forEach(b=>b.onchange=()=>toggleTask(b.dataset.complete,b.checked));}
function toggleTask(id,done){const t=taskById(id),before=structuredClone(t);t.done=done;t.state=done?'done':'pending';changeRecord('task-state',id,before,t);render();notify('只更新此 Task，父子状态独立')}
function openMore(id,e){captureEditor();$('.refine-menu')?.remove();const menu=document.createElement('div');menu.className='refine-menu';menu.innerHTML=[['properties','日期 / 移动清单 / 关联父任务'],['complete','完成 / 重新打开'],['abandon','放弃'],['clear-time','取消时间安排'],['child','添加子任务'],['unlink','解除父任务'],['discuss','与 Codex 讨论'],['delete','删除 Task']].map(([k,n])=>`<button data-menu-op="${k}">${n}</button>`).join('');menu.setAttribute('popover','manual');($('#detail-dialog').open?$('#detail-dialog'):document.body).append(menu);menu.showPopover();menu.style.left=Math.min(e?.clientX||innerWidth-260,innerWidth-270)+'px';menu.style.top=Math.min(e?.clientY||180,innerHeight-330)+'px';menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{menu.remove();const t=taskById(id),before=structuredClone(t),op=b.dataset.menuOp;if(op==='properties'){if($('#detail-dialog').open)$('#detail-dialog').close();openRefineTask(t);$('#refine-task-form .property-chip').open=true;return}if(op==='child'){if($('#detail-dialog').open)$('#detail-dialog').close();return openRefineTask(null,null,null,demoDate,id)}if(op==='discuss'){if($('#detail-dialog').open)$('#detail-dialog').close();return action('discuss:'+id)}if(op==='complete')return toggleTask(id,!t.done);if(op==='abandon'){t.state='abandoned';t.done=false}if(op==='unlink')t.parent=null;if(op==='clear-time'){t.time=null;t.duration=null}if(op==='delete'){tasks=tasks.filter(x=>x.id!==id);tasks.filter(x=>x.parent===id).forEach(x=>x.parent=null);selectedTask=null;detailKind=null;}taskDraft=null;taskDraftId=null;changeRecord(op,id,before,op==='delete'?null:t);if($('#detail-dialog').open)$('#detail-dialog').close();render();notify(op==='clear-time'?'已取消时间，日期和 Task 身份保留':op==='delete'?'共享 Task 已删除；子任务保留': 'Task 已更新')});}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.refine-menu,[data-more],[data-context-task]'))$('.refine-menu')?.remove()});
function axisRange(){if(axisExpanded)return [240,1680];if(variant==='C'&&focusBand!=='all')return focusBand==='am'?[360,720]:focusBand==='pm'?[720,1080]:[1080,1440];return [360,1440]}
function axisScale(){const [a,b]=axisRange(),available=Math.max(100,innerHeight-350-(variant==='C'?115:variant==='A'&&innerWidth<=720?120:0));if(zoomMode==='fine'||variant==='B'&&zoomMode==='default')return 1;if(innerWidth<=720&&zoomMode==='default')return .65;if(variant==='C'&&focusBand!=='all')return Math.min(1.4,available/(b-a));return available/(b-a);}
function refineAxisItems(scale){return assignAxisLanes([
 ...plans.map(p=>({kind:'plan',id:p.id,start:anchorOf(p),end:Math.max(p.end??anchorOf(p)+45,anchorOf(p)+30/scale),value:p})),
 ...tasks.filter(t=>t.date===demoDate&&t.time!=null&&!t.done&&t.state!=='abandoned').map(t=>({kind:'task',id:t.id,start:t.time,end:t.time+Math.max(t.duration??15,30/scale),value:t})),
 ...facts.filter(f=>f.time!=null).map(f=>({kind:'fact',id:f.id,start:f.time,end:f.time+30/scale,value:f}))
 ].sort((a,b)=>a.start-b.start));}
function refineTimeline(){const [start,end]=axisRange(),scale=axisScale(),items=refineAxisItems(scale).filter(i=>i.start>=start&&i.start<end);return `<div class="refine-axis-scroll"><div class="refine-axis" data-refine-axis data-start="${start}" data-end="${end}" data-scale="${scale}" style="height:${(end-start)*scale}px;--hour:${60*scale}px">${Array.from({length:Math.ceil((end-start)/(scale<.25?180:60))},(_,i)=>{const m=start+i*(scale<.25?180:60);return `<span class="unified-tick" style="top:${(m-start)*scale}px">${m>=1440?'次日 ':''}${time(m%1440)}</span>`}).join('')}${items.map(i=>{const p=i.value,caption=i.kind==='fact'?'事实 · '+time(p.time):i.kind==='task'?time(p.time)+(p.duration!=null?'–'+time(p.time+p.duration):'')+' · Task':refinePlanLabel(p),style=`top:${(i.start-start)*scale}px;left:${i.lane*100/i.lanes}%;width:calc(${100/i.lanes}% - 4px);height:${Math.max(30,((i.kind==='plan'?p.end==null?45:p.end-p.start:i.kind==='task'?p.duration??15:25)*scale))}px`;return `<${i.kind==='fact'?'div':'button'} class="unified-item ${i.kind} ${i.kind==='plan'&&p.start==null?'approximate':''}" ${i.kind==='fact'?'':`data-axis-kind="${i.kind}" data-axis-id="${i.id}"`} style="${style}" title="${esc(caption+' · '+p.name)}"><span class="unified-caption">${esc(caption)}</span><strong>${esc(p.name)}</strong>${i.kind==='plan'&&p.start!=null?`<span class="refine-resize" data-resize="${p.id}" title="拖动结束时间"></span>`:''}</${i.kind==='fact'?'div':'button'}>`}).join('')}<div class="refine-drop" hidden></div></div></div>`;}
function dayTaskShelf(){const dated=tasks.filter(t=>t.date===demoDate);return `<div class="day-task-shelf"><div class="section-title"><h2>当日任务 · ${dated.filter(t=>!t.done&&t.state!=='abandoned').length} 待办</h2><button class="text-button" data-action="tasks">全部任务 ↗</button></div>${dated.filter(t=>t.time==null||t.done||t.state==='abandoned').map(taskRow).join('')}<p class="tiny muted">已记录：桌面整理完成，时刻未记。</p></div>`}
function planEditorMarkup(p){return `<form id="refine-plan-form" data-id="${p.id}"><div class="editor-head"><span class="tiny muted">当前安排 · ${p.id}</span><button type="button" class="text-button" id="close-plan">✕</button></div><h2>${esc(p.name)}</h2><p>${esc(p.note)}</p><label>时间精度<select id="refine-precision"><option value="exact" ${p.start!=null?'selected':''}>精确起止</option><option value="broad" ${p.start==null?'selected':''}>宽泛 / 近似</option></select></label><div id="plan-exact" ${p.start==null?'hidden':''} class="time-pair"><label>开始<input id="refine-plan-start" type="time" value="${time(anchorOf(p)%1440)}"></label><label>结束<input id="refine-plan-end" type="time" value="${time((p.end??anchorOf(p)+60)%1440)}"></label></div><div id="plan-broad" ${p.start!=null?'hidden':''}><label>时段<select id="refine-period">${['早晨','中午','下午','晚间','约定时刻'].map(x=>`<option ${p.band===x||x==='约定时刻'&&p.band.startsWith('约')?'selected':''}>${x}</option>`).join('')}</select></label><label>近似时刻<input id="refine-anchor" type="time" value="${time(anchorOf(p)%1440)}"></label></div><p class="tiny muted">白天调整更新当前安排，早间基准独立保留。</p><div class="editor-footer"><button class="btn primary">Save</button><button class="btn" type="button" id="cancel-plan-edit">Cancel</button></div><button type="button" class="text-button" id="remove-plan">取消当前安排</button></form>`;}
function bindPlanEditor(root,p){const f=root.querySelector('#refine-plan-form');if(!f)return;const close=()=>{if($('#detail-dialog').open)$('#detail-dialog').close();else{selectedPlan=null;detailKind=null;render()}};$('#close-plan').onclick=close;$('#cancel-plan-edit').onclick=close;$('#refine-precision').onchange=e=>{$('#plan-exact').hidden=e.target.value!=='exact';$('#plan-broad').hidden=e.target.value==='exact'};f.onsubmit=e=>{e.preventDefault();let next;if($('#refine-precision').value==='exact'){const start=minuteOf($('#refine-plan-start').value),end=minuteOf($('#refine-plan-end').value);if(start==null||end==null||end<=start){notify('请填写有效起止时间');return}next={start,end,anchor:start,band:bandOf(start)}}else{const period=$('#refine-period').value,anchor=period==='约定时刻'?minuteOf($('#refine-anchor').value):{早晨:540,中午:720,下午:780,晚间:1080}[period];if(anchor==null)return;next={start:null,end:null,anchor,band:period==='约定时刻'?'约 '+time(anchor):period}}if($('#detail-dialog').open)$('#detail-dialog').close();commitPlan(p.id,next,'edit-current-arrangement')};$('#remove-plan').onclick=()=>{const before=structuredClone(p);plans=plans.filter(x=>x.id!==p.id);changeRecord('cancel-current-arrangement',p.id,before,null);selectedPlan=null;detailKind=null;$('#detail-dialog').close();render();notify('当前安排已取消，早间基准保留')};}
function openRefinePlan(id){selectedPlan=id;selectedTask=null;detailKind='plan';const p=plans.find(x=>x.id===id);if(variant==='B'){render();return}const d=$('#detail-dialog');d.className='refine-plan-dialog';d.innerHTML=planEditorMarkup(p);d.showModal();bindPlanEditor(d,p)}
function detailRail(){return `<aside class="refine-detail today-detail">${detailKind==='task'&&taskById(selectedTask)?taskEditor(taskById(selectedTask)):detailKind==='plan'&&plans.find(p=>p.id===selectedPlan)?planEditorMarkup(plans.find(p=>p.id===selectedPlan)):'<p class="muted">点时间轴里的任务或安排，在这里编辑。</p>'+dayTaskShelf()}</aside>`}
today=()=>{const date=selectedDate();if(phase==='evening')return header('今天',date+' · 合成记录')+phaseTabs()+(selectedDay===10?evening():`<section class="surface"><h2>${date} · 晚间复盘</h2><p>${dayStatus(selectedDay)==='reviewed'?'阅读完成，其余活动没有记录。':'尚未记录晚间复盘。'}</p></section>`);if(phase==='morning')return header('今天',date+' · 合成记录')+phaseTabs()+revisionMorningText();if(selectedDay!==10)return header('日期回顾',date+' · 合成样例')+phaseTabs()+`<section class="surface"><h2>${date}</h2><p>${dayStatus(selectedDay)==='reviewed'?'早间计划：留出阅读和活动时间。晚间复盘：阅读完成，其余活动未记录。':'尚无 Daily Record；创建 Task 不补造记录。'}</p>${tasks.filter(t=>t.date===date).map(taskRow).join('')}</section>`;
 return header('今天','10 月 10 日 · 周六 · 合成样例',btn('与 Codex 讨论','collaboration'))+phaseTabs()+`<div class="day-controls"><div class="unified-legend"><span class="plan">□ 当前安排</span><span class="task">○ Task</span><span class="fact">● 事实</span></div><div class="inline-actions"><button class="btn" id="zoom-axis">${zoomMode==='fine'||variant==='B'&&zoomMode==='default'?'一屏概览':'精细放大'}</button><button class="text-button" id="expand-axis">${axisExpanded?'收起边界':'04:00–次日04:00'}</button><button class="text-button" data-document-preview>对应文档</button></div></div>${variant==='C'?`<div class="focus-bands">${[['all','全日'],['am','上午'],['pm','下午'],['eve','晚间']].map(([k,n])=>`<button data-focus="${k}" aria-pressed="${focusBand===k}">${n}</button>`).join('')}</div>`:''}<div class="refine-today variant-${variant}"><section class="surface axis-surface">${refineTimeline()}</section>${variant==='B'?detailRail():variant==='A'?dayTaskShelf():''}</div>${variant==='C'?dayTaskShelf():''}`;};
function bindRefineAxis(){const axis=$('[data-refine-axis]');if(!axis)return;const start=+axis.dataset.start,end=+axis.dataset.end,scale=+axis.dataset.scale,scroller=axis.closest('.refine-axis-scroll'),drop=axis.querySelector('.refine-drop');let drag=null;const minute=y=>Math.max(start,Math.min(end-15,Math.round((y-axis.getBoundingClientRect().top)/scale/15)*15+start));axis.onpointerdown=e=>{const item=e.target.closest('[data-axis-id]');if(!item)return;e.preventDefault();const resize=e.target.closest('[data-resize]');drag={id:item.dataset.axisId,kind:item.dataset.axisKind,resize:!!resize,y:e.clientY,offset:Math.round((e.clientY-item.getBoundingClientRect().top)/scale/15)*15,moved:false};axis.setPointerCapture(e.pointerId)};axis.onpointermove=e=>{if(!drag)return;if(Math.abs(e.clientY-drag.y)>5)drag.moved=true;if(!drag.moved)return;autoScroll(scroller,e.clientY);const m=minute(e.clientY)-(drag.resize?0:drag.offset);drop.hidden=false;drop.style.top=(m-start)*scale+'px';drop.textContent=(drag.resize?'结束 ':'移动至 ')+time(m%1440)};axis.onpointerup=e=>{stopScroll();if(!drag)return;const d=drag;drag=null;drop.hidden=true;if(!d.moved){window.refineAnchor=axis.querySelector('[data-axis-id="'+d.id+'"]').getBoundingClientRect();if(d.kind==='task')selectTask(d.id);else openRefinePlan(d.id);return}const m=minute(e.clientY)-(d.resize?0:d.offset);if(d.kind==='task'){const t=taskById(d.id),before=structuredClone(t);t.time=Math.max(start,Math.min(end-(t.duration??15),m));changeRecord('drag-task',t.id,before,t);render();notify('Task 已移位，执行区间时长保留')}else{const p=plans.find(x=>x.id===d.id);if(d.resize)commitPlan(p.id,{end:Math.max(p.start+15,Math.min(end,m))},'resize-current-plan');else if(p.start==null){const anchor=Math.max(start,Math.min(end-15,m));commitPlan(p.id,{anchor,band:'约 '+time(anchor%1440)},'drag-approximate-plan')}else{const duration=p.end-p.start,a=Math.max(start,Math.min(end-duration,m));commitPlan(p.id,{start:a,end:a+duration,anchor:a},'drag-exact-plan')}}};axis.onpointercancel=()=>{drag=null;drop.hidden=true;stopScroll()};}
function monthMarkup(){return `<div class="week-head">${['日','一','二','三','四','五','六'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:35},(_,i)=>{const n=i-3,valid=n>0&&n<=31,items=tasks.filter(t=>t.date===dateFor(n)),holiday=holidayVisible?({1:'国庆 · 中',2:'国庆 · 中',12:'Columbus · 美',31:'Halloween · 美'})[n]:null;return `<div class="calendar-day ${n===selectedDay?'selected':''} ${n===10?'today':''}"><button class="calendar-date-button" ${valid?`data-refine-day="${n}"`:'disabled'} aria-label="选择 10 月 ${n} 日"><strong>${valid?n:n<1?n+30:n-31}</strong>${valid&&dayStatus(n)!=='missing'?`<small class="record-marker">${dayStatus(n)==='reviewed'?'复':'记'}</small>`:''}</button>${holiday?`<span class="holiday" title="合成节日样例">${holiday}</span>`:''}${items.slice(0,4).map(t=>`<button class="calendar-task ${t.done?'done':''}" data-task="${t.id}" title="${esc(t.name)}">${esc(t.name)}</button>`).join('')}${items.length>4?`<button class="calendar-more" data-refine-day="${n}">＋ ${items.length-4} 项</button>`:''}</div>`}).join('')}</div>`;}
function recordPreview(){const n=selectedDay,status=dayStatus(n),plan=n===10?plans.map(p=>`<p><b>${refinePlanLabel(p)}</b> · ${esc(p.name)}</p>`).join(''):status==='reviewed'?'<p>早间计划：留出阅读和活动时间。</p>':'<p class="muted">未建立 Daily Record</p>',review=status==='reviewed'?'<p>阅读完成。其余活动没有记录，保持未知。</p>':n===10?'<p>阅读 25 分钟、桌面整理完成。晚间复盘未填写。</p>':'<p class="muted">未记录复盘。</p>';return `<aside class="surface refine-record-preview"><div class="section-title"><h2>10 月 ${n} 日</h2><span class="pill">${status==='reviewed'?'复盘':status==='unreviewed'?'记录':'空白'}</span></div>${variant==='B'?`<div class="preview-tabs"><button data-preview-tab="plan" aria-pressed="${previewTab==='plan'}">计划</button><button data-preview-tab="review" aria-pressed="${previewTab==='review'}">复盘</button></div>${previewTab==='plan'?plan:review}`:variant==='C'?`<details open><summary>当天计划</summary>${plan}</details><details open><summary>记录与复盘</summary>${review}</details>`:`<h3>当天计划</h3>${plan}<h3>记录与复盘</h3>${review}`}<h3>Task · ${tasks.filter(t=>t.date===dateFor(n)).length}</h3>${tasks.filter(t=>t.date===dateFor(n)).map(taskRow).join('')}<button class="btn" id="open-full-today">Open full Today ↗</button></aside>`;}
calendarPage=()=>header('日历','2026 年 10 月 · 先选日期，再从顶部添加',`<label class="holiday-toggle"><input id="holidays" type="checkbox" ${holidayVisible?'checked':''}>中 / 美节日样例</label><button class="btn primary" id="calendar-add" aria-label="新增所选日期任务">＋</button>`)+`<div class="refine-calendar"><section class="surface refine-month">${monthMarkup()}<p class="tiny muted">记：已有记录 · 复：已有晚间复盘 · 节日仅合成样例</p></section>${recordPreview()}</div>`;
const mockCommands=[['/retro','个人复盘 · 现有入口'],['/retro-week','多候选演示 · 非真实命令'],['/retro-day','多候选演示 · 非真实命令']];
function refineContext(){return `<aside class="refine-context context-${variant}"><div class="context-heading"><b>当前背景</b><button class="text-button" data-action="context">收起 ✕</button></div><div class="context-scroll"><p><b>目标日期</b> ${demoDate}</p><h3>当前安排</h3>${plans.map(p=>`<p>${refinePlanLabel(p)} · ${esc(p.name)}</p>`).join('')}<h3>Tasks</h3>${tasks.filter(t=>!t.done).map(t=>`<p>${esc(t.name)} · ${t.date||'未排期'}</p>`).join('')}<h3>已记录</h3><p>阅读 25 分钟；桌面已整理。其余活动未知。</p><h3>早间基准</h3>${baseline.map(p=>`<p>${refinePlanLabel(p)} · ${esc(p.name)}</p>`).join('')}</div></aside>`;}
function voiceMarkup(){if(voiceState==='idle'&&!voiceText)return '';return `<section class="voice-preview"><div class="context-heading"><b>${voiceState==='recording'?'模拟转写中':'转写预览 · 已进入可编辑草稿'}</b><button type="button" class="text-button" id="voice-fold">${voiceExpanded?'收起':'展开'}</button></div>${voiceExpanded?`<p>${esc(voiceText||'等待模拟片段…')}</p>`:''}${voiceState==='recording'?'<div class="inline-actions"><button class="btn" type="button" id="voice-chunk">加入下一片段</button><button class="btn primary" type="button" id="voice-stop">停止并放入草稿</button><button class="text-button" type="button" id="voice-cancel">取消听写</button></div>':'<button type="button" class="text-button" id="voice-clear">收起预览</button>'}</section>`;}
collaboration=()=>header('协作','今天的安排 · 目标日期 10 月 10 日',btn('新对话','new-chat')+btn(showContext?'收起背景':'查看背景','context'))+`<div class="refine-chat variant-${variant} ${showContext?'context-open':''}">${variant==='B'?sessions():''}<section class="chat-main"><div class="chat-top"><b>${emptyChat?'新对话':'今天的安排'}</b>${variant!=='B'?btn(showSessions?'收起会话':'会话','sessions'):''}</div>${showSessions&&variant!=='B'?`<div class="inline-session">${btn('今天的安排','select-chat')}${btn('最近一周复盘','sample-retro')}</div>`:''}<div class="messages">${messages.length?messages.map(messageMarkup).join(''):'<div class="empty-chat"><p>从一句话开始</p><small>输入 / 查看补全，语音仅模拟。</small></div>'}</div>${showContext&&variant==='A'?refineContext():''}<form class="composer" id="composer"><div class="command-menu" role="listbox" aria-label="模拟多候选" id="command-menu" hidden></div><div class="composer-box"><textarea id="message-draft" aria-label="协作消息" aria-controls="command-menu" placeholder="说说今天的情况…">${esc(draft)}</textarea><div class="composer-bottom"><small>⌘ Enter 发送</small><button type="button" class="text-button" id="voice-start">${voiceState==='recording'?'模拟听写中…':'🎙 模拟听写'}</button><button class="btn primary" ${voiceState==='recording'?'disabled':''}>发送</button></div></div>${voiceMarkup()}</form></section>${showContext&&variant!=='A'?refineContext():''}</div>`;
commandMatch=()=>{const i=$('#message-draft');return !!i&&!commandDismissed&&/^\/[a-z-]*$/i.test(i.value.slice(0,i.selectionStart))&&mockCommands.some(([c])=>c.startsWith(i.value.slice(0,i.selectionStart)))};
function matchingCommands(){const i=$('#message-draft');return mockCommands.filter(([c])=>c.startsWith(i.value.slice(0,i.selectionStart)))}
updateCommandMenu=()=>{const menu=$('#command-menu'),i=$('#message-draft');if(!menu)return;menu.hidden=!commandMatch();i.setAttribute('aria-expanded',String(!menu.hidden));if(menu.hidden)return;const matches=matchingCommands();slashIndex=Math.min(slashIndex,matches.length-1);menu.innerHTML=`<div class="menu-caption">模拟多候选 · 只有 /retro 是现有入口</div>${matches.map(([c,label],n)=>`<button type="button" class="command-option" role="option" aria-selected="${n===slashIndex}" data-command-index="${n}"><code>${c}</code><span>${label}</span><kbd>${n===slashIndex?'Tab ↵':''}</kbd></button>`).join('')}`;menu.querySelectorAll('[data-command-index]').forEach(b=>b.onclick=()=>{slashIndex=+b.dataset.commandIndex;completeCommand()})};
completeCommand=()=>{const i=$('#message-draft'),c=matchingCommands()[slashIndex]?.[0]||'/retro';draft=c+' '+i.value.slice(i.selectionStart);i.value=draft;i.focus();i.setSelectionRange(c.length+1,c.length+1);commandDismissed=true;updateCommandMenu();notify('已补全文本，尚未发送')};
function finishVoice(cancel=false){if(voiceState!=='recording')return;voiceState=cancel?'idle':'done';if(cancel)voiceText='';else draft=(draft?draft+'\n':'')+voiceText;render();if(page==='collaboration')$('#message-draft').focus();notify(cancel?'模拟听写已取消':'转写进入可编辑草稿，尚未发送')}
function bindRefineChat(){const i=$('#message-draft');if(!i)return;i.oninput=()=>{draft=i.value;commandDismissed=false;slashIndex=0;updateCommandMenu()};i.onkeydown=e=>{if(completionVisible()&&['ArrowUp','ArrowDown','Enter','Tab','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape')commandDismissed=true;else if(e.key==='ArrowDown'||e.key==='ArrowUp')slashIndex=(slashIndex+(e.key==='ArrowDown'?1:-1)+matchingCommands().length)%matchingCommands().length;else return completeCommand();return updateCommandMenu()}if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();if(voiceState!=='recording')sendMessage()}};$('#composer').onsubmit=e=>{e.preventDefault();if(voiceState!=='recording')sendMessage()};$('#voice-start').onclick=()=>{if(voiceState==='recording')return;voiceState='recording';voiceText='我想把下午的安排留得松一点。';voiceExpanded=true;render()};$('#voice-fold')?.addEventListener('click',()=>{voiceExpanded=!voiceExpanded;render()});$('#voice-chunk')?.addEventListener('click',()=>{voiceText+=' 晚上先买菜，再留时间休息。';render()});$('#voice-stop')?.addEventListener('click',()=>finishVoice());$('#voice-cancel')?.addEventListener('click',()=>finishVoice(true));$('#voice-clear')?.addEventListener('click',()=>{voiceText='';voiceState='idle';render()});updateCommandMenu()}
const dayISO=d=>d.toISOString().slice(0,10),dateObj=d=>new Date(d+'T12:00:00Z'),addDays=(d,n)=>{const x=dateObj(d);x.setUTCDate(x.getUTCDate()+n);return dayISO(x)},weekStart=d=>{const x=dateObj(d);return addDays(d,-((x.getUTCDay()+6)%7))};
function buildHabits(){return [{id:'h1',name:'活动身体',emoji:'🚶',group:'生活',start:'2026-07-01',goal:{frequency:'weekly',target:3,kind:'days'},pending:null,inactive:false,coverageStart:'2026-07-01',full:true},{id:'h2',name:'阅读',emoji:'📚',group:'学习',start:'2026-01-01',goal:{frequency:'daily',target:1,kind:'days'},pending:null,inactive:false,coverageStart:'2026-09-14',full:false},{id:'h3',name:'按时起床',emoji:'🌤',group:'生活',start:'2026-07-01',goal:{frequency:'daily',target:1,kind:'threshold',threshold:'08:00'},pending:null,inactive:false,coverageStart:'2026-07-01',full:true}].map((h,j)=>({...h,historyGoals:[{effective:h.start,goal:structuredClone(h.goal)}],local:Array.from({length:102},(_,i)=>addDays('2026-07-01',i)).filter((d,i)=>d>=h.coverageStart&&d<=demoDate&&(j===0?[0,2,4].includes(dateObj(d).getUTCDay()):j===1?i%8!==0:i%7!==1)),mapped:j===0?['2026-10-06','2026-10-08']:[]}))}
let habits=buildHabits();
function goalAt(h,d){return [...h.historyGoals].reverse().find(g=>g.effective<=d)?.goal||h.goal}
function habitStats(h){const attained=new Set([...h.local,...h.mapped]),dates=[...attained].filter(d=>d>=h.coverageStart&&d<=demoDate),month=dates.filter(d=>d.startsWith('2026-10')).length;let cycles=[];if(h.goal.frequency==='weekly'){let w=weekStart(h.coverageStart);for(;w<=weekStart(demoDate);w=addDays(w,7)){const goal=goalAt(h,w),count=dates.filter(d=>d>=w&&d<addDays(w,7)).length,complete=addDays(w,6)<=demoDate;cycles.push({date:w,attained:count>=goal.target,complete,partial:w<h.coverageStart})}}else for(let d=h.coverageStart;d<=demoDate;d=addDays(d,1))cycles.push({date:d,attained:attained.has(d),complete:true});let max=0,run=0;for(const c of cycles.filter(c=>!c.partial&&(c.complete||c.attained))){run=c.attained?run+1:0;max=Math.max(run,max)}let current=0,closed=cycles.filter(c=>!c.partial&&(c.complete||c.attained));if(h.goal.frequency==='daily'&&!attained.has(demoDate))closed=closed.filter(c=>c.date!==demoDate);for(let i=closed.length-1;i>=0&&closed[i].attained;i--)current++;const currentWeek=dates.filter(d=>d>=weekStart(demoDate)).length;return {month,total:dates.length,current,max,currentWeek,attained:[...attained]};}
function habitDetail(h){const s=habitStats(h),unit=h.goal.frequency==='weekly'?'周':'天';return `<div class="habit-detail-head"><div><span class="habit-icon">${h.emoji}</span><h2>${esc(h.name)}</h2><p>${goalLabel(h.goal)} · 开始于 ${h.start}</p></div><button class="btn" data-edit-habit="${h.id}">编辑</button></div>${h.pending?`<p class="pending-goal">待生效：${goalLabel(h.pending.goal)} · ${h.pending.effective} 起<br><small>本周期继续按 ${goalLabel(h.goal)} 统计；历史保留原目标。</small></p>`:''}<div class="habit-stat-grid">${[['本月打卡',s.month+' 天'],[h.full?'累计打卡':'覆盖内打卡',s.total+' 天'],['当前连续达标',s.current+' '+unit],[h.full?'最高连续达标':'覆盖内最高连续',s.max+' '+unit]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><p class="coverage-note">${h.full?'完整合成历史：':'有限合成覆盖：'}${h.coverageStart}–${demoDate}${h.full?'':' · 全历史累计与最高连续未知'}</p>${h.goal.frequency==='weekly'?`<div class="weekly-progress"><b>本周 ${s.currentWeek} / ${h.goal.target} 天</b><p>同日重复完成、本地与外部证据合并只算一个达标天。</p></div>`:''}<div class="section-title"><h3>10 月打卡</h3><small>${h.goal.kind==='threshold'?'记录达标，不推断实际起床时间':'点击日期查看 / 撤回本地完成'}</small></div><div class="habit-month">${Array.from({length:31},(_,i)=>{const d=dateFor(i+1),local=h.local.includes(d),mapped=h.mapped.includes(d),on=s.attained.includes(d);return `<button data-habit-day="${d}" data-habit-id="${h.id}" ${d>demoDate||d<h.start||d<h.coverageStart?'disabled':''} class="${on?'attained':''}" title="${d} · ${local?'本地完成 ':''}${mapped?'外部证据':''}">${i+1}${on?' ✓':''}</button>`}).join('')}</div><div class="inline-actions"><button class="btn primary" data-check-habit="${h.id}" ${h.inactive?'disabled':''}>${h.goal.kind==='threshold'?'今天已达到阈值':'今天打卡'}</button><button class="text-button" data-check-habit="${h.id}">重复打卡演示</button><button class="text-button" data-toggle-habit="${h.id}">${h.inactive?'恢复习惯':'停用习惯'}</button></div><div class="tiny muted habit-source"><p>今天：${h.local.includes(demoDate)?'本地达标':'无本地完成'}${h.mapped.includes(demoDate)?' · 外部也有证据':''}</p>${h.mapped.length?`<p>10 月 6 日：${h.local.includes('2026-10-06')?'本地 ':''}${h.mapped.includes('2026-10-06')?'外部证据':''}（可撤回本地后观察）</p>`:''}</div>`;}
function habitsPage(){const h=habits.find(x=>x.id===habitSelected),visible=habits.filter(x=>showInactive||!x.inactive);return header('习惯','本地创建 · 按达标天数统计',`<button class="btn" id="inactive-habits">${showInactive?'收起停用':'查看停用'}</button><button class="btn primary" id="new-habit" aria-label="新增习惯">＋</button>`)+`<section class="surface refine-habits variant-${variant}"><aside class="habit-list">${['生活','学习','其他'].map(g=>{const hs=visible.filter(x=>x.group===g);return hs.length?`<h3>${g}</h3>${hs.map(x=>`<button data-select-habit="${x.id}" data-context-habit="${x.id}" class="${x.id===habitSelected?'active':''}"><span>${x.emoji}</span>${esc(x.name)}${x.inactive?'<small>停用</small>':''}<small>${goalLabel(x.goal)}</small></button>`).join('')}`:''}).join('')}</aside><div class="habit-detail">${h?habitDetail(h):'<p>选择习惯查看详情</p>'}</div></section>`;}
function openHabitEditor(h=null){const value=h?{...h,...h.pending?{goal:h.pending.goal}:{} }:{id:null,name:'',emoji:'🌱',group:'生活',start:demoDate,goal:{frequency:'daily',target:1,kind:'days',threshold:'08:00'}},d=$('#detail-dialog');d.className='refine-habit-dialog';d.innerHTML=`<h2>${h?'编辑':'创建本地'} Habit</h2><form id="habit-form"><label>名称<input name="name" value="${esc(value.name)}" required></label><div class="time-pair"><label>图标<select name="emoji">${['🌱','🚶','📚','🌤','🧘','💧'].map(x=>`<option ${value.emoji===x?'selected':''}>${x}</option>`).join('')}</select></label><label>分组<select name="group">${['生活','学习','其他'].map(x=>`<option ${value.group===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label>频率 / 目标<select name="frequency" id="habit-frequency"><option value="daily" ${value.goal.frequency==='daily'?'selected':''}>每天</option><option value="weekly" ${value.goal.frequency==='weekly'?'selected':''}>每周</option></select></label><div id="habit-weekly" ${value.goal.frequency!=='weekly'?'hidden':''}><label>每周达标天数<select name="target">${Array.from({length:7},(_,i)=>`<option value="${i+1}" ${value.goal.target===i+1?'selected':''}>${i+1} 天 / 周</option>`).join('')}</select></label></div><div id="habit-daily" ${value.goal.frequency!=='daily'?'hidden':''}><label>每天目标<select name="kind" id="habit-kind"><option value="days" ${value.goal.kind==='days'?'selected':''}>当天完成</option><option value="threshold" ${value.goal.kind==='threshold'?'selected':''}>时间阈值前达标</option></select></label><label id="threshold-field" ${value.goal.kind!=='threshold'?'hidden':''}>阈值<input type="time" name="threshold" value="${value.goal.threshold||'08:00'}"></label></div><label>开始日期<input type="date" name="start" value="${value.start}" required></label>${h?`<p class="pending-goal">当前：${goalLabel(h.goal)}<br>目标修改从${h.goal.frequency==='weekly'?'下周 10 月 12 日':'次日 10 月 11 日'}生效；历史统计不重算。</p>`:''}<div class="editor-footer"><button class="btn primary">${h?'Save':'创建'}</button><button type="button" class="btn" id="habit-cancel">Cancel</button></div></form>`;d.showModal();$('#habit-frequency').onchange=e=>{$('#habit-weekly').hidden=e.target.value!=='weekly';$('#habit-daily').hidden=e.target.value!=='daily'};$('#habit-kind').onchange=e=>$('#threshold-field').hidden=e.target.value!=='threshold';$('#habit-cancel').onclick=()=>d.close();$('#habit-form').onsubmit=e=>{e.preventDefault();const v=new FormData(e.target),frequency=String(v.get('frequency')),goal={frequency,target:frequency==='weekly'?+v.get('target'):1,kind:frequency==='weekly'?'days':String(v.get('kind')),...(frequency==='daily'&&v.get('kind')==='threshold'?{threshold:String(v.get('threshold'))}:{})};if(h){const before=structuredClone(h);Object.assign(h,{name:String(v.get('name')),emoji:String(v.get('emoji')),group:String(v.get('group')),start:String(v.get('start'))});if(JSON.stringify(goal)!==JSON.stringify(h.goal)){h.pending={effective:h.goal.frequency==='weekly'?'2026-10-12':'2026-10-11',goal};}else h.pending=null;changeRecord('edit-habit',h.id,before,h)}else{const added={id:'habit-'+Date.now(),name:String(v.get('name')),emoji:String(v.get('emoji')),group:String(v.get('group')),start:String(v.get('start')),goal,pending:null,historyGoals:[{effective:String(v.get('start')),goal:structuredClone(goal)}],coverageStart:String(v.get('start')),full:true,local:[],mapped:[],inactive:false};habits.push(added);habitSelected=added.id;changeRecord('create-habit',added.id,null,added)}d.close();render();notify(h?(h.pending?'Habit 已保存，目标从下一周期生效':'Habit 已保存，历史保留'):'本地 Habit 已创建，可以直接打卡')};}
const refineOriginalAction=action;
action=value=>{if(value==='new-task')return openRefineTask();if(value==='close-task'){selectedTask=null;detailKind=null;return render()}if(value==='context'){captureEditor();showContext=!showContext;return render()}if(value==='dictation')return $('#voice-start')?.click();if(value==='today')selectedDay=10;return refineOriginalAction(value)};
navigate=next=>{captureEditor();if(page==='collaboration'&&voiceState==='recording'){voiceState='done';draft=(draft?draft+'\n':'')+voiceText;notify('模拟转写保留在原会话草稿')}page=next;render();if(page==='tasks')$('#task-content')?.focus();};
cycle=direction=>{captureEditor();const keys=Object.keys(refineVariants);variant=keys[(keys.indexOf(variant)+direction+keys.length)%keys.length];zoomMode='default';render();};
function bindCommon(root=document){root.querySelectorAll('[data-task]').forEach(b=>b.onclick=e=>{window.refineAnchor=e.currentTarget.getBoundingClientRect();selectTask(b.dataset.task)});root.querySelectorAll('[data-more]').forEach(b=>b.onclick=e=>openMore(b.dataset.more,e));root.querySelectorAll('[data-complete]').forEach(c=>c.onchange=()=>toggleTask(c.dataset.complete,c.checked));root.querySelectorAll('[data-context-task]').forEach(b=>b.oncontextmenu=e=>{e.preventDefault();openMore(b.dataset.contextTask,e)});}
bind=()=>{document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{captureEditor();phase=b.dataset.phase;render()});bindCommon();document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{captureEditor();scope=b.dataset.scope;render()});$('#folder-arrow')?.addEventListener('click',()=>{folderOpen=!folderOpen;render()});[['task-sort','taskSort'],['priority-filter','priorityFilter'],['tag-filter','tagFilter']].forEach(([id,name])=>$('#'+id)?.addEventListener('change',e=>{if(name==='taskSort')taskSort=e.target.value;if(name==='priorityFilter')priorityFilter=e.target.value;if(name==='tagFilter')tagFilter=e.target.value;render()}));document.querySelectorAll('[data-quick-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const v=new FormData(f),t={id:'demo-'+Date.now(),name:String(v.get('name')),note:'',date:String(v.get('date'))||null,time:null,duration:null,list:String(v.get('list')),priority:'无',tags:[],parent:null,state:'pending',done:false};tasks.push(t);changeRecord('quick-add',t.id,null,t);render();notify('已创建共享 Task；目标清单 '+t.list)});
 const t=taskById(selectedTask);if($('#refine-task-form')&&t)bindTaskEditor(document,t,false);if($('#refine-plan-form'))bindPlanEditor(document,plans.find(p=>p.id===selectedPlan));
 $('#zoom-axis')?.addEventListener('click',()=>{captureEditor();zoomMode=zoomMode==='fine'||variant==='B'&&zoomMode==='default'?'overview':'fine';render()});$('#expand-axis')?.addEventListener('click',()=>{axisExpanded=!axisExpanded;render()});document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{focusBand=b.dataset.focus;zoomMode='default';$('.refine-axis-scroll').scrollTop=0;render()});document.querySelectorAll('[data-document-preview]').forEach(b=>b.onclick=showMarkdown);bindRefineAxis();
 document.querySelectorAll('[data-refine-day]').forEach(b=>b.onclick=()=>{selectedDay=+b.dataset.refineDay;render()});$('#calendar-add')?.addEventListener('click',()=>openRefineTask(null,null,null,selectedDate()));$('#holidays')?.addEventListener('change',e=>{holidayVisible=e.target.checked;render()});document.querySelectorAll('[data-preview-tab]').forEach(b=>b.onclick=()=>{previewTab=b.dataset.previewTab;render()});$('#open-full-today')?.addEventListener('click',()=>{phase=dayStatus(selectedDay)==='reviewed'?'evening':'daytime';navigate('today')});bindRefineChat();
 $('#new-habit')?.addEventListener('click',()=>openHabitEditor());$('#inactive-habits')?.addEventListener('click',()=>{showInactive=!showInactive;render()});document.querySelectorAll('[data-select-habit]').forEach(b=>b.onclick=()=>{habitSelected=b.dataset.selectHabit;render()});document.querySelectorAll('[data-edit-habit]').forEach(b=>b.onclick=()=>openHabitEditor(habits.find(h=>h.id===b.dataset.editHabit)));document.querySelectorAll('[data-context-habit]').forEach(b=>b.oncontextmenu=e=>{e.preventDefault();openHabitEditor(habits.find(h=>h.id===b.dataset.contextHabit))});document.querySelectorAll('[data-toggle-habit]').forEach(b=>b.onclick=()=>{const h=habits.find(h=>h.id===b.dataset.toggleHabit);h.inactive=!h.inactive;if(h.inactive){habitSelected=habits.find(x=>!x.inactive)?.id||null}render();notify(h.inactive?'Habit 已停用，历史与统计保留':'Habit 已恢复')});document.querySelectorAll('[data-check-habit]').forEach(b=>b.onclick=()=>{const h=habits.find(h=>h.id===b.dataset.checkHabit);if(h.inactive||h.start>demoDate){notify(h.inactive?'停用 Habit 请先恢复':'Habit 尚未开始');return}const exists=h.local.includes(demoDate);if(!exists)h.local.push(demoDate);changeRecord('habit-check',h.id,exists,habitStats(h));render();notify(exists?'同日重复打卡，达标天数不增加':'已记录本地达标')});document.querySelectorAll('[data-habit-day]').forEach(b=>b.onclick=()=>{const h=habits.find(h=>h.id===b.dataset.habitId),day=b.dataset.habitDay;if(h.inactive){notify('停用 Habit 请先恢复');return}if(h.local.includes(day))h.local=h.local.filter(x=>x!==day);else h.local.push(day);render();notify(h.mapped.includes(day)?'本地完成已切换；外部证据仍独立支持达标':'本地完成已切换')});};
render=()=>{const oldAxis=$('.refine-axis-scroll')?.scrollTop,oldMessages=$('.messages')?.scrollTop;updateUrl();document.body.dataset.variant=variant;$('.app-shell').dataset.workspaceDestination=page;document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));$('#page').innerHTML=page==='today'?today():page==='tasks'?taskPage():page==='calendar'?calendarPage():page==='habits'?habitsPage():collaboration();$('#variant-name').textContent=variant+' · '+refineVariants[variant][0];$('#variant-description').textContent=refineVariants[variant][1];bind();if($('.refine-axis-scroll'))$('.refine-axis-scroll').scrollTop=oldAxis??(axisScale()>=.6&&axisRange()[0]<480?(480-axisRange()[0])*axisScale()-8:0);if($('.messages'))$('.messages').scrollTop=oldMessages||0;const overlay=$('.context-C')||(innerWidth<=720?$('.context-B'):null);if(overlay){overlay.style.maxHeight=Math.max(40,$('.composer').getBoundingClientRect().top-$('.refine-chat').getBoundingClientRect().top-55)+'px'};};
